"""Freeze external enum/identity/rule/trigger/RLS contexts before evaluation."""
import hashlib
import json
from datetime import datetime,timezone
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'reports/validation-expansion4'


def main():
    if (OUT/'frozen.json').exists():raise SystemExit('Never overwrite frozen cases')
    sources=json.loads((OUT/'sources/downloads.json').read_text());cases=[]
    def add(name,file,statement,baseline,table,column,expected,probe='',state=None,
            migration_state=None,values=None,key='id',holdout=False,hazard=False,admin=False):
        source=next(s for s in sources if s['path'].endswith('/'+file))
        body=(OUT/'sources'/file).read_bytes();assert hashlib.sha256(body).hexdigest()==source['sha256']
        assert statement in body.decode(),statement
        directory=OUT/'inputs'/name;directory.mkdir(parents=True)
        value=dict(initial='12',created='13',old_write='14',new_write='15',new_update='16',old_update='17');value.update(values or {})
        (directory/'input.json').write_text(json.dumps(dict(id=name,table=table,key=key,old_column=column,new_column=column,values=value,provenance={k:source[k] for k in ('repository','revision','path','sha256')}),indent=2)+'\n')
        (directory/'baseline.sql').write_text(baseline+'\n');(directory/'candidate.sql').write_text(statement+'\n')
        cases.append(dict(id=name,split='holdout' if holdout else 'development',difficulty='Advanced',category='external_sql',
                          source=dict(source,extracted_statement=statement),expected_verdict=expected,oracle_sql=probe,
                          oracle_state=state,migration_state=migration_state,out_of_scope_hazard=hazard,
                          database_role='superuser_control' if admin else 'least_privilege'))
    planets="CREATE TYPE planets AS ENUM('venus','earth','mars'); CREATE TABLE world(id int PRIMARY KEY,value planets); INSERT INTO world VALUES(1,'venus');"
    pv=dict(initial='venus',created='earth',old_write='mars',new_write='venus',new_update='earth',old_update='mars')
    add('enum-add-late-value','enum.sql',"ALTER TYPE planets ADD VALUE 'uranus';",planets,'world','value','GO_WITHIN_SCOPE',
        "INSERT INTO world VALUES(201,'uranus') RETURNING value::text='uranus'",values=dict(pv,old_write='uranus'))
    add('enum-add-before','enum.sql',"ALTER TYPE planets ADD VALUE 'mercury' BEFORE 'venus';",planets,'world','value','GO_WITHIN_SCOPE',
        "INSERT INTO world VALUES(201,'mercury') RETURNING value::text='mercury'",values=dict(pv,old_write='mercury'),holdout=True)
    rainbow="CREATE TYPE rainbow AS ENUM('red','orange','yellow','green','blue','purple'); CREATE TABLE colors(id int PRIMARY KEY,value rainbow); INSERT INTO colors VALUES(1,'red');"
    rv=dict(initial='red',created='orange',old_write='red',new_write='green',new_update='yellow',old_update='purple')
    add('enum-rename-existing','enum.sql',"ALTER TYPE rainbow RENAME VALUE 'red' TO 'crimson';",rainbow,'colors','value','BLOCK',
        "INSERT INTO colors VALUES(201,'red')",'22P02',values=rv)
    add('enum-renamed-late-write','enum.sql',"ALTER TYPE rainbow RENAME VALUE 'red' TO 'crimson';",rainbow.replace("VALUES(1,'red')","VALUES(1,'green')"),
        'colors','value','BLOCK',"INSERT INTO colors VALUES(201,'red')",'22P02',values=dict(rv,initial='green'),holdout=True)
    add('enum-duplicate-label','enum.sql',"ALTER TYPE planets ADD VALUE 'mercury';",planets.replace("'mars')","'mars','mercury')"),
        'world','value','INCONCLUSIVE',migration_state='42710',values=pv)
    add('enum-missing-neighbor','enum.sql',"ALTER TYPE planets ADD VALUE 'pluto' AFTER 'zeus';",planets,
        'world','value','INCONCLUSIVE',migration_state='22023',values=pv,holdout=True)
    add('identity-always-explicit-key','identity.sql','ALTER TABLE itest4 ALTER COLUMN a ADD GENERATED ALWAYS AS IDENTITY;',
        "CREATE TABLE itest4(a int PRIMARY KEY,b text); INSERT INTO itest4 VALUES(1,'12');",'itest4','b','BLOCK',
        "INSERT INTO itest4(a,b) VALUES(201,'13')",'428C9',key='a')
    add('identity-drop-explicit-key','identity.sql','ALTER TABLE itest4 ALTER COLUMN a DROP IDENTITY;',
        "CREATE TABLE itest4(a int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,b text); INSERT INTO itest4 VALUES(1,'12');",'itest4','b','GO_WITHIN_SCOPE',
        "INSERT INTO itest4(a,b) VALUES(201,'13') RETURNING b='13'",key='a',holdout=True)
    add('identity-restart-unmapped-key','identity.sql','ALTER TABLE itest6 ALTER COLUMN a SET GENERATED BY DEFAULT SET INCREMENT BY 2 SET START WITH 100 RESTART;',
        "CREATE TABLE itest6(a int GENERATED BY DEFAULT AS IDENTITY(START WITH 200) PRIMARY KEY,b text); INSERT INTO itest6 VALUES(1,'12');",'itest6','b','GO_WITHIN_SCOPE',
        "INSERT INTO itest6(b) VALUES('x')",'23505',key='a',hazard=True)
    add('identity-add-unmapped-column','identity.sql','ALTER TABLE itest13 ADD COLUMN b int GENERATED BY DEFAULT AS IDENTITY;',
        "CREATE TABLE itest13(id int PRIMARY KEY,payload text); INSERT INTO itest13 VALUES(1,'12');",'itest13','payload','GO_WITHIN_SCOPE',
        "INSERT INTO itest13(id,payload) VALUES(201,'x') RETURNING b IS NOT NULL")
    rule10='create rule rtest_nothn_r1 as on insert to rtest_nothn1\n\twhere new.a >= 10 and new.a < 20 do instead nothing;'
    rule30='create rule rtest_nothn_r2 as on insert to rtest_nothn1\n\twhere new.a >= 30 and new.a < 40 do instead nothing;'
    rulebase='CREATE TABLE rtest_nothn1(id int PRIMARY KEY,a int,b text); INSERT INTO rtest_nothn1 VALUES(1,1,NULL);'
    small=dict(initial='1',created='2',old_write='3',new_write='4',new_update='5',old_update='6')
    add('conditional-rule-ignored-insert','rules.sql',rule10,rulebase,'rtest_nothn1','a','BLOCK',
        ['INSERT INTO rtest_nothn1(id,a) VALUES(201,12)','SELECT count(*)=0 FROM rtest_nothn1 WHERE id=201'],values=dict(small,old_write='12'))
    add('conditional-rule-safe-values','rules.sql',rule10,rulebase,'rtest_nothn1','a','GO_WITHIN_SCOPE',
        ['INSERT INTO rtest_nothn1(id,a) VALUES(201,2)','SELECT count(*)=1 FROM rtest_nothn1 WHERE id=201'],values=small)
    add('conditional-rule-other-range','rules.sql',rule30,rulebase,'rtest_nothn1','a','BLOCK',
        ['INSERT INTO rtest_nothn1(id,a) VALUES(201,31)','SELECT count(*)=0 FROM rtest_nothn1 WHERE id=201'],values=dict(small,new_write='31'),holdout=True)
    add('rule-all-inserts-ignored','rules.sql','create rule rtest_nothn_r4 as on insert to rtest_nothn2\n\tdo instead nothing;',
        'CREATE TABLE rtest_nothn2(id int PRIMARY KEY,a int,b text); INSERT INTO rtest_nothn2 VALUES(1,1,NULL);','rtest_nothn2','a','BLOCK',
        ['INSERT INTO rtest_nothn2(id,a) VALUES(201,2)','SELECT count(*)=0 FROM rtest_nothn2 WHERE id=201'],values=small)
    function='create function f1_times_10() returns trigger as\n$$ begin new.f1 := new.f1 * 10; return new; end $$ language plpgsql;'
    assert function in (OUT/'sources/triggers.sql').read_text()
    trig='create trigger trigger_alpha\n\tbefore insert or update on trigtest\n\tfor each row execute procedure f1_times_10();'
    add('trigger-changes-mapped-value','triggers.sql',trig,
        'CREATE TABLE trigtest(id int PRIMARY KEY,f1 int,f2 text); INSERT INTO trigtest(id,f1) VALUES(1,12); '+function,
        'trigtest','f1','BLOCK','INSERT INTO trigtest(id,f1) VALUES(201,2) RETURNING f1=20')
    add('trigger-disable-unmapped-derived','triggers.sql','alter table trigtest disable trigger user;',
        "CREATE TABLE trigtest(id int PRIMARY KEY,f1 int DEFAULT 1,f2 text); "+function+' '+trig+" INSERT INTO trigtest(id,f2) VALUES(1,'12');",
        'trigtest','f2','GO_WITHIN_SCOPE',"INSERT INTO trigtest(id,f2) VALUES(201,'x') RETURNING f1=1",holdout=True,hazard=True)
    force='ALTER TABLE r1 FORCE ROW LEVEL SECURITY;'
    policybase='CREATE TABLE r1(id int PRIMARY KEY,a int); INSERT INTO r1 VALUES(1,12); CREATE POLICY p1 ON r1 USING(false); ALTER TABLE r1 ENABLE ROW LEVEL SECURITY;'
    add('rls-owner-force-deny','rowsecurity.sql',force,policybase,'r1','a','BLOCK',
        'INSERT INTO r1 VALUES(201,12)','42501')
    add('rls-owner-force-allow','rowsecurity.sql',force,policybase.replace('USING(false)','USING(true)'),
        'r1','a','GO_WITHIN_SCOPE','SELECT count(*)=1 FROM r1 WHERE id=1')
    add('rls-superuser-bypass-control','rowsecurity.sql',force,policybase,'r1','a','GO_WITHIN_SCOPE',
        'SELECT NOT row_security_active(\'r1\')',admin=True,hazard=True)
    add('rls-enable-owner-bypass','rowsecurity.sql','ALTER TABLE r1 ENABLE ROW LEVEL SECURITY;',
        'CREATE TABLE r1(id int PRIMARY KEY,a int); INSERT INTO r1 VALUES(1,12); CREATE POLICY p1 ON r1 USING(false);',
        'r1','a','GO_WITHIN_SCOPE',"SELECT NOT row_security_active('r1')",hazard=True)
    add('rls-remove-force','rowsecurity.sql','ALTER TABLE r1 NO FORCE ROW LEVEL SECURITY;',
        policybase.replace('USING(false)','USING(true)')+' '+force,'r1','a','GO_WITHIN_SCOPE',"SELECT NOT row_security_active('r1')")
    read_hidden='CREATE TABLE r1(id int PRIMARY KEY,a int); INSERT INTO r1 VALUES(1,12); CREATE POLICY p1 ON r1 FOR SELECT USING(false); CREATE POLICY p2 ON r1 FOR INSERT WITH CHECK(true); ALTER TABLE r1 ENABLE ROW LEVEL SECURITY;'
    add('rls-hidden-read-allowed-insert','rowsecurity.sql',force,read_hidden,'r1','a','BLOCK',
        ['INSERT INTO r1 VALUES(201,12)','SELECT count(*)=0 FROM r1 WHERE id=201'],holdout=True)
    checkbase='CREATE TABLE r1(id int PRIMARY KEY,a int); INSERT INTO r1 VALUES(1,1); CREATE POLICY p1 ON r1 USING(true) WITH CHECK(a<20); ALTER TABLE r1 ENABLE ROW LEVEL SECURITY;'
    add('rls-check-rejects-late-write','rowsecurity.sql',force,checkbase,'r1','a','BLOCK',
        'INSERT INTO r1 VALUES(201,42)','42501',values=dict(small,old_write='42'))
    add('rls-check-valid-write','rowsecurity.sql',force,checkbase,'r1','a','GO_WITHIN_SCOPE',
        'INSERT INTO r1 VALUES(201,19) RETURNING a=19',values=small,holdout=True)
    counts={split:sum(c['split']==split for c in cases) for split in ('development','holdout')}
    frozen=dict(frozen_at=datetime.now(timezone.utc).isoformat(),cases=cases,requires_least_privilege=True,
                input_sha256={str(p.relative_to(OUT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((OUT/'inputs').rglob('*')) if p.is_file()},
                acceptance='All confirmed references must match verdict and exit. Unresolved references do not count as correct. No post-result input/label changes. Freeze fixes before opening holdout.',
                role_boundary='One explicitly labeled superuser bypass control; every other case uses NOSUPERUSER NOBYPASSRLS. Synthetic HTTP fixture uses the same provided DSN.',
                context_boundary='External SQL and one upstream PLpgSQL function excerpt, evaluator-authored schema/data/mapping. No new customer application integration.')
    (OUT/'frozen.json').write_text(json.dumps(frozen,indent=2)+'\n');(OUT/'frozen.sha256').write_text(hashlib.sha256((OUT/'frozen.json').read_bytes()).hexdigest()+'\n')
    print('Frozen',len(cases),'cases',counts)


if __name__=='__main__':main()
